  border-left-color: var(--line-strong, #cbd5e1) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.reading-treatment-item:hover,
.reading-category-item:hover {
  border-color: var(--line-strong, #cbd5e1);
  border-left-color: var(--blue-hover, #2563eb) !important;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.08);
